import {createMobileControlPreview} from './mobile-controls.mjs';
import {controlLayout,normalizeControlLayout,saveControlLayout,applyControlLayout,measureControlArea,editableControlElements,controlPosition} from './mobile-preferences.mjs';
import {loadSolo} from './campaign-profile.mjs';
import {SOLO_SKILLS} from './campaign-growth-data.mjs';
import {duelChoiceStyle} from './duel-skill-ui.mjs';
import {skillArtStyle} from './skill-icons.mjs';
let styleReady;
function styles(){return styleReady??=new Promise((resolve,reject)=>{const link=document.createElement('link');link.rel='stylesheet';link.href='mobile-control-editor.css';link.onload=resolve;link.onerror=()=>{styleReady=null;link.remove();reject(Error('按键编辑界面未能载入，请重试'));};document.head.append(link);});}
function previewModel(storage){const p=loadSolo(storage||globalThis.localStorage),hero=p.selected||'fire',record=p.heroes[hero],skills={attack:{name:'普攻',style:skillArtStyle(hero,'attack')},dash:{name:'闪避',style:skillArtStyle(hero,'dash')}};for(const key of ['q','e','r']){const s=SOLO_SKILLS[hero].find(x=>x.id===record.slots[key])||SOLO_SKILLS[hero].find(x=>x.key===key);skills[key]={name:s.name,style:duelChoiceStyle(hero,s)};}return {hero,skills};}
const label={joystick:'移动摇杆',attack:'普攻',jump:'跳跃',dash:'闪避',q:'F技能',e:'E技能',r:'R技能',artifact:'法器',context:'交互'};
export function overlappingControls(root){const a=[...editableControlElements(root)].map(([role,e])=>({role,rect:e.getBoundingClientRect()}));const pairs=[];for(let i=0;i<a.length;i++)for(let j=i+1;j<a.length;j++){const x=a[i].rect,y=a[j].rect;if(Math.min(x.right,y.right)-Math.max(x.left,y.left)>5&&Math.min(x.bottom,y.bottom)-Math.max(x.top,y.top)>5)pairs.push([a[i].role,a[j].role]);}return pairs;}
export class MobileControlEditor{
 constructor({storage}={}){
  this.storage=storage;this.contacts=new Map();this.el=document.createElement('dialog');this.el.className='mobile-control-editor';this.el.setAttribute('aria-labelledby','mobile-editor-title');this.el.innerHTML='<div class="mobile-editor-backdrop" aria-hidden="true"></div><header class="mobile-editor-header"><div><h2 id="mobile-editor-title">自定义按键</h2><p>拖动按键，调整到顺手的位置</p></div><nav aria-label="布局操作"><button type="button" data-layout-default>恢复默认</button><button type="button" data-layout-cancel>取消</button><button type="button" data-layout-save>保存布局</button></nav></header><p class="mobile-editor-status" role="status">菜单与暂停位置保持固定</p><div class="mobile-editor-stage"></div>';
  document.body.append(this.el);this.el.querySelector('[data-layout-default]').onclick=()=>{this.cancelDrags();this.draft=normalizeControlLayout(null);applyControlLayout(this.preview,this.draft);this.validate('已恢复默认预览，保存后生效');};this.el.querySelector('[data-layout-cancel]').onclick=()=>this.close();this.el.querySelector('[data-layout-save]').onclick=()=>this.save();this.el.addEventListener('cancel',e=>{e.preventDefault();this.close();});this.el.addEventListener('close',()=>this.finish());this.el.addEventListener('pointerdown',e=>this.down(e),{passive:false});this.el.addEventListener('pointermove',e=>this.move(e),{passive:false});this.el.addEventListener('pointerup',e=>this.up(e),{passive:false});this.el.addEventListener('pointercancel',e=>this.up(e,true),{passive:false});this.el.addEventListener('lostpointercapture',e=>{if(this.contacts.has(e.pointerId))this.up(e,true);});this.el.addEventListener('click',e=>{if(e.target.closest('.mobile-editor-controls')){e.preventDefault();e.stopPropagation();}});window.addEventListener('resize',()=>{if(this.el.open){this.cancelDrags();applyControlLayout(this.preview,this.draft);this.validate();}});window.addEventListener('keydown',e=>{if(!this.el.open)return;e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();this.close();}},true);window.addEventListener('arcane-background',()=>{if(this.el.open)this.close();});
 }
 async open(){if(this.el.open||this.opening)return;this.opening=true;try{await styles();this.draft=controlLayout(this.storage);this.preview=createMobileControlPreview({model:previewModel(this.storage)});this.el.querySelector('.mobile-editor-stage').replaceChildren(this.preview);this.previousFocus=document.activeElement;this.active=true;window.dispatchEvent(new CustomEvent('arcane-controls-edit',{detail:{active:true}}));this.el.showModal();applyControlLayout(this.preview,this.draft);this.areaObserver?.disconnect();this.areaObserver=new ResizeObserver(()=>{if(this.el.open){this.cancelDrags();applyControlLayout(this.preview,this.draft);this.validate();}});this.areaObserver.observe(this.preview.querySelector('.mobile-layout-safe-area'));this.validate();}catch(e){this.finish();throw e;}finally{this.opening=false;}}
 block(event){if(event.cancelable)event.preventDefault();event.stopPropagation();}
 down(event){const target=event.target.closest('[data-mobile-role]');if(!target||!this.preview.contains(target))return;this.block(event);const role=target.dataset.mobileRole;if(!label[role]||this.contacts.has(event.pointerId)||[...this.contacts.values()].some(p=>p.role===role))return;const r=target.getBoundingClientRect();this.contacts.set(event.pointerId,{role,target,offset:{x:event.clientX-r.x-r.width/2,y:event.clientY-r.y-r.height/2},before:this.draft.positions[role]?{...this.draft.positions[role]}:null});target.classList.add('is-dragging');target.setPointerCapture(event.pointerId);this.status('正在调整：'+label[role]);}
 move(event){const drag=this.contacts.get(event.pointerId);if(!drag)return;this.block(event);const r=drag.target.getBoundingClientRect(),area=measureControlArea(this.preview);this.draft.positions[drag.role]=controlPosition({x:event.clientX-drag.offset.x,y:event.clientY-drag.offset.y},{width:r.width,height:r.height},area);applyControlLayout(this.preview,this.draft);this.validate('已调整：'+label[drag.role]);}
 up(event,cancel=false){const drag=this.contacts.get(event.pointerId);if(!drag)return;this.block(event);if(!cancel)this.move(event);this.contacts.delete(event.pointerId);if(cancel){if(drag.before)this.draft.positions[drag.role]=drag.before;else delete this.draft.positions[drag.role];applyControlLayout(this.preview,this.draft);}drag.target.classList.remove('is-dragging');try{drag.target.releasePointerCapture(event.pointerId);}catch{}this.validate();}
 cancelDrags(){for(const [id,drag]of this.contacts){drag.target.classList.remove('is-dragging');try{drag.target.releasePointerCapture(id);}catch{}}this.contacts.clear();}
 status(text){this.el.querySelector('.mobile-editor-status').textContent=text;}
 validate(message){const conflicts=overlappingControls(this.preview);this.el.querySelector('[data-layout-save]').disabled=conflicts.length>0;this.preview.querySelectorAll('.has-overlap').forEach(e=>e.classList.remove('has-overlap'));if(conflicts.length){for(const roles of conflicts)for(const role of roles)this.preview.querySelector('[data-mobile-role="'+role+'"]').classList.add('has-overlap');this.status(label[conflicts[0][0]]+'与'+label[conflicts[0][1]]+'有重叠，请稍微分开');}else this.status(message||'拖动调整 · 菜单与暂停保持固定');return !conflicts.length;}
 save(){this.cancelDrags();if(!this.validate())return;if(!saveControlLayout(this.draft,this.storage)){this.status('当前设备无法保存，请稍后重试；原布局未更改');return;}this.close();}
 close(){this.cancelDrags();if(this.el.open)this.el.close();else this.finish();}
 finish(){if(!this.active)return;this.active=false;this.areaObserver?.disconnect();this.cancelDrags();window.dispatchEvent(new CustomEvent('arcane-controls-edit',{detail:{active:false}}));this.previousFocus?.focus?.();}
}
